{"expression": "(() => {
  const q = s => Array.from(document.querySelectorAll(s));
  const hdrs = q('[data-testid="conversation-info-header"]');
  const comps = q('[data-testid="conversation-compose-box-input"]');
  const selfRows = q('[data-testid="cell-frame-title"]');
  const panel = q('[data-testid="conversation-panel-wrapper"]')[0] || null;
  const msgs = q('[data-testid="msg-container"]');
  const canary = document.body.innerText.includes('Teste técnico Hermes Work — 13/11/2026');
  return {
    url: location.href,
    headerCount: hdrs.length,
    headerTexts: hdrs.map(h => (h.textContent || '').trim().slice(0, 80)),
    headerChatIds: hdrs.map(h => h.getAttribute('data-chat-id')),
    composerCount: comps.length,
    composerAria: comps.map(c => c.getAttribute('aria-label')),
    selfRowTitles: selfRows.map(r => ({ text: (r.textContent || '').trim().slice(0, 60), testid: r.getAttribute('data-testid') })),
    panelWrapper: !!panel,
    msgCount: msgs.length,
    canaryPresent: canary
  };
})()"}
